CREATE TABLE `cdk`  (   `ID` int(11) NOT NULL AUTO_INCREMENT,   `CDK` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `Itemcode` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `itemName` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `number` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `species` int(11) NOT NULL,   `Tickets` int(11) NOT NULL,   `Tokens` int(11) NOT NULL,   `strengthen` int(11) NOT NULL,   `Increase` int(11) NOT NULL,   `amplification` int(11) NOT NULL,   `forge` int(11) NOT NULL,   `pet` tinyint(1) NOT NULL,   `exchange` tinyint(1) NOT NULL,   `grouping` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `Redemptiontime` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `Generationtime` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `uid` int(11) NOT NULL,   `cid` int(11) NOT NULL,   `rolename` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `colour` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   PRIMARY KEY (`ID`) USING BTREE,   UNIQUE INDEX `UNIQUE_CDKEY`(`CDK`) USING BTREE ) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;
CREATE TABLE `cdk_copy`  (   `ID` int(11) NOT NULL AUTO_INCREMENT,   `CDK` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `Itemcode` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `itemName` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `number` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `species` int(11) NOT NULL,   `Tickets` int(11) NOT NULL,   `Tokens` int(11) NOT NULL,   `strengthen` int(11) NOT NULL,   `Increase` int(11) NOT NULL,   `amplification` int(11) NOT NULL,   `forge` int(11) NOT NULL,   `pet` tinyint(1) NOT NULL,   `exchange` tinyint(1) NOT NULL,   `grouping` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `Redemptiontime` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `Generationtime` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `uid` int(11) NOT NULL,   `cid` int(11) NOT NULL,   `rolename` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `colour` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   `limit_type` int(11) NOT NULL,   `linmit_num` int(11) NOT NULL,   PRIMARY KEY (`ID`) USING BTREE,   UNIQUE INDEX `UNIQUE_CDKEY`(`CDK`) USING BTREE ) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;
CREATE TABLE  `dof_native`.`cdk_solid_stat`  (   `id` int(15) NOT NULL AUTO_INCREMENT COMMENT '自增的主键',   `cdk_id` int(11) NOT NULL,   `m_id` int(11) NOT NULL,   `cid` int(11) NOT NULL,   PRIMARY KEY USING BTREE (`id`) ) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Compact;
CREATE TABLE `Listofcheats` (  `ID` int(11) unsigned NOT NULL auto_increment,  `UID` int(11) NOT NULL,  `Name` varchar(255) NOT NULL,  `QQ` varchar(255) NOT NULL,  `behavior` varchar(1024) NOT NULL,  `Time` varchar(1024) NOT NULL,  PRIMARY KEY  (`ID`)) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE `billing` (`ID` int(11) NOT NULL auto_increment,`ip_reg_control` int(11) NOT NULL,`regnumber` int(11) NOT NULL,`bubbleCount` int(11) NOT NULL, `bubbleType` int(11) NOT NULL,`bubbleTime` int(11) NOT NULL,`register` int(11) NOT NULL,`regtype` int(11) NOT NULL,`uidsecure` int(11) NOT NULL,`decrypt` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,   PRIMARY KEY  (`ID`)) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;
