CREATE TABLE `qfillegal` (  `CID` int(11) NOT NULL auto_increment,  `IUID` varchar(255) character set utf8 NOT NULL,  `IUsername` varchar(255) character set utf8 NOT NULL,  `IFile_md5` varchar(255) character set utf8 NOT NULL,  `IMac_md5` varchar(255) character set utf8 NOT NULL,  `MING` varchar(255) character set utf8 NOT NULL,  `IKey_word` varchar(255) character set utf8 NOT NULL,  `IIPAddress` varchar(255) NOT NULL,  `ITime` varchar(1024) NOT NULL,  PRIMARY KEY  (`CID`)) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1 ROW_FORMAT=DYNAMIC;
CREATE TABLE `fightingcapacity` (  `ID` int(11) NOT NULL auto_increment,  `Name` varchar(255) character set utf8 NOT NULL,  `price` int(11) NOT NULL,  `Lv` int(11) NOT NULL,  `CID` int(11) NOT NULL,  `blacklist` int(11) NOT NULL,  `mobai_num` int(11) NOT NULL,  `occupation` varchar(255) character set utf8 NOT NULL,  `Equipment` varchar(255) character set utf8 NOT NULL,  PRIMARY KEY  (`ID`)) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;
CREATE TABLE `Dummylist` (  `ID` int(11) NOT NULL auto_increment,  `YID` varchar(255) character set utf8 NOT NULL,  `UID` varchar(255) character set utf8 NOT NULL,  `port` varchar(255) character set utf8 NOT NULL,  `curvill` varchar(255) character set utf8 NOT NULL,  `curarea` varchar(255) character set utf8 NOT NULL,  `curx` varchar(255) character set utf8 NOT NULL,  `cury` varchar(255) character set utf8 NOT NULL,  `CID` varchar(255) character set utf8 NOT NULL,  `ip` varchar(100) character set utf8 default NULL COMMENT '假人服务的IP，摆摊和交易假人要用服务器外网IP',  `function_type` int(11) default NULL COMMENT '功能类型  0普通 1交易  2摆摊 3分解',  `discost` int(11) default NULL COMMENT '分解机价格，功能类型=3分解时有效',  PRIMARY KEY  (`ID`)) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;
CREATE TABLE `gift_task` (  `task_id` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '任务ID',   `task_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '任务名称',   `task_type` int(10) NOT NULL COMMENT '任务类型  1=固定人数(抽取模式)   2=不限人数(幸运模式)',   `region_id` int(10) NOT NULL COMMENT '区域ID    -1=不限制区域',   `room_id` int(10) NOT NULL COMMENT '房间ID    区域不为-1，但房间为-1则不限制房间',   `user_num` int(10) NOT NULL COMMENT '抽取的玩家数，task_type=1时此字段有效',   `code_num` int(10) NOT NULL COMMENT '抽取的最大道具数量',   `task_state` int(10) NOT NULL COMMENT '任务状态  1=开启   0=关闭',   `gift_odds` int(10) NOT NULL COMMENT '用户中奖几率  0-100    task_type=2时字段有效，越大中奖几率越高',   `gift_type` int(10) NOT NULL COMMENT '奖励随机   1=每个中奖玩家道具都随机   0=每个中奖玩家道具都一样',   `task_time` int(10) NOT NULL COMMENT '定时多久发放一次(分钟) 不能为0否则会一分钟发一次',   `task_last_time` int(15) NOT NULL COMMENT '上次奖励发放时间 unix_timestamp(now())/60',   `name2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '公告内容与公告类型',   PRIMARY KEY USING BTREE (`task_id`) ) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;
CREATE TABLE `gift_history` (  `id` int(15) NOT NULL AUTO_INCREMENT COMMENT '自增的主键',   `task_id` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '任务ID',   `create_time` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '奖励时间',   `content` varchar(3000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '本期奖励内容',   PRIMARY KEY USING BTREE (`id`) ) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;
CREATE TABLE `gift_code` (  `id` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT 'ID',   `task_id` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '任务ID  对应gift_task表的task_id',   `code_id` int(15) NOT NULL COMMENT '道具代码',   `code_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '道具名称',   `code_num` int(10) NOT NULL COMMENT '道具数量',   `code_odds` int(10) NOT NULL COMMENT '道具进入奖池的几率  0-100    越大作为奖励道具的几率越高',   `code_state` int(10) NOT NULL COMMENT '道具状态  1=可用  0=不可用',   PRIMARY KEY USING BTREE (`id`) ) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;
CREATE TABLE `gift_user` (  `cid` int(11) NOT NULL,   `region` int(10) NULL DEFAULT NULL COMMENT '区域ID',   `room` int(10) NULL DEFAULT NULL COMMENT '房间ID',   PRIMARY KEY USING BTREE (`cid`) ) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;
CREATE TABLE `map_task` (  `task_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '任务ID  自增',   `task_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '任务名称',   `map_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '副本名称',   `reward_state` int(10) NOT NULL COMMENT '是否奖励道具  1奖励  0不奖励',   `msg_state` int(10) NOT NULL COMMENT '是否公告  1发送  0不发',   `msg_text` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '组队公告内容',   `task_state` int(10) NOT NULL COMMENT '任务状态  1开启  0停用',   `msg_single_text` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '单人公告内容',   `is_steam_reward` int(10) NOT NULL COMMENT '是否必须组队才给奖励  1组队才给  0单人也给',   PRIMARY KEY USING BTREE (`task_id`) ) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;
CREATE TABLE `map_history` (  `ID` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,   `uid` int(11) NOT NULL COMMENT 'uid',   `charactName` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '角色名',   `dungeonId` int(11) NOT NULL COMMENT '副本ID',   `dungeonName` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '副本名',   `difficulty` int(11) NOT NULL COMMENT '难度',   `mapCount` int(11) NOT NULL COMMENT '小地图数量',   `killMobCount` int(11) NOT NULL COMMENT '杀怪数量',   `useCubepieceClearCount` int(11) NOT NULL COMMENT '无色使用数量',   `hell` int(11) NOT NULL COMMENT '是否深渊',   `passingTime` int(11) NOT NULL COMMENT '通过时间',   `clearInfo` int(11) NOT NULL COMMENT '跟success相关',   `success` int(11) NOT NULL COMMENT '通关为时1 当clearInfo也为1时 是翻牌后点击的返回城镇 当为0 且 clearInfo也为0时 是掉线了',   `leaveTime` datetime NOT NULL COMMENT '离开副本的时间',   `reward_state` int(11) NOT NULL COMMENT '是否已发放公告  1已发  0未发',   `is_captain` int(11) NOT NULL COMMENT '是否队长  1队长  0队员  队长才发公告',   `is_team` int(11) NOT NULL COMMENT '团队人数  大于1才算团队 否则都是单人',   `c_id` int(11) NOT NULL COMMENT '角色ID',   `msg_text` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '公告内容',   PRIMARY KEY USING BTREE (`ID`) ) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;
CREATE TABLE `map_code` (  `id` int(10) NOT NULL AUTO_INCREMENT,   `task_id` int(10) NOT NULL COMMENT 'map_task表中的task_id',   `code_id` int(15) NOT NULL COMMENT '道具代码',   `code_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '道具名称',   `code_num` int(10) NOT NULL COMMENT '道具数量',   `code_odds` int(10) NOT NULL COMMENT '道具奖励几率  0-100  越高越容易中',   `code_state` int(10) NOT NULL COMMENT '道具状态  1=可用  0=不可用',   PRIMARY KEY USING BTREE (`id`) ) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;
CREATE TABLE `titles` (  `seal_ip` int(11) UNSIGNED NOT NULL DEFAULT 1,   `seal_mac` int(11) UNSIGNED NOT NULL DEFAULT 1,   `seal_uid`  int(11) UNSIGNED NOT NULL DEFAULT 1,   `seal_announcement`  int(11) UNSIGNED NOT NULL DEFAULT 1,   `seal_content` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL ) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;
CREATE TABLE `robot` (  `robot` int(11) NOT NULL auto_increment,  `aiState` varchar(255) character set utf8 NOT NULL,  `speed` varchar(255) character set utf8 NOT NULL,  PRIMARY KEY  (`robot`)) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;
