CREATE TABLE `regCdkey`  (`ID` int(11) UNSIGNED NOT NULL AUTO_INCREMENT, `Cdkey` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL, `accountname` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL, `State` int(11) NOT NULL, PRIMARY KEY(`ID`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Compact;
CREATE TABLE `randombox` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
