  `item_num` int(11) NOT NULL,
  `Probability` int(11) NOT NULL,
  `Announcement` int(11) NOT NULL,
  `Grouping` int(11) NOT NULL,
  `rarity` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
